if ( ! function_exists( 'nexora_ph_ce_icon' ) ) {
	/**
	 * One icon body by key; unknown keys render nothing.
	 *
	 * @param string $key Icon key.
	 */
	function nexora_ph_ce_icon( $key ): string {
		$icons = nexora_ph_ce_icons();
		$key   = (string) $key;

		return isset( $icons[ $key ] ) ? $icons[ $key ] : '';
	}
}
